import React, { useState } from 'react';
import { Star } from 'lucide-react';
import { RatingStars } from '@/components/client/RatingStars';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';

export default function RatePage() {
    const [rating, setRating] = useState(0);
    const [comment, setComment] = useState('');
    const [submitted, setSubmitted] = useState(false);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        // Mock submit
        setSubmitted(true);
        // Reset after a while
        setTimeout(() => setSubmitted(false), 3000);
    };

    return (
        <div className="p-6 max-w-lg mx-auto space-y-6">
            <h1 className="text-2xl font-light text-white">Avaliar Atendimento</h1>
            {submitted ? (
                <p className="text-green-400">Obrigado pela avaliação!</p>
            ) : (
                <form onSubmit={handleSubmit} className="space-y-4">
                    <div>
                        <label className="block text-sm font-medium text-gray-300 mb-1">Nota</label>
                        <RatingStars rating={rating} onRate={setRating} />
                    </div>
                    <Input
                        label="Comentário (opcional)"
                        type="text"
                        value={comment}
                        onChange={(e) => setComment(e.target.value)}
                        placeholder="Deixe seu comentário"
                    />
                    <Button type="submit" className="w-full" size="lg" isLoading={false}>
                        Enviar Avaliação
                    </Button>
                </form>
            )}
        </div>
    );
}
